mapper.select:
SELECT EMPLOYEE_ID, EMPLOYEE_NAME, DEPARTMENT, POSITION_TITLE, SALARY, DENSE_RANK() OVER (ORDER BY SALARY DESC) AS SALARY_RANK, DENSE_RANK() OVER (PARTITION BY DEPARTMENT ORDER BY SALARY DESC) AS DEPT_RANK, ROUND(PERCENT_RANK() OVER (ORDER BY SALARY) * 100, 1) AS PERCENTILE, ROUND(CUME_DIST() OVER (ORDER BY SALARY) * 100, 1) AS CUMULATIVE_PCT, NTILE(3) OVER (ORDER BY SALARY DESC) AS SALARY_TIER FROM EMPLOYEES
DEPARTMENT = #{department}
ORDER BY SALARY DESC
